entries[30312] = { ["name"] = "Teufelseisenmuskete", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchwerer Griff , Teufelseisengehäuse (3), Eine Hand voll Teufelseisenbolzen (6)\nTeufelseisenmuskete\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n99 - 185 Schaden Tempo 2.80\n(50.71 Schaden pro Sekunde)\n+14 Ausdauer\nHaltbarkeit 65 / 65\n63" }
entries[30313] = { ["name"] = "Adamantitgewehr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nTeufelseisengehäuse (3), Adamantitrahmen (2), Eine Hand voll Teufelseisenbolzen (4)\nAdamantitgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n126 - 234 Schaden Tempo 3.00\n(60.00 Schaden pro Sekunde)\n+12 Beweglichkeit\nHaltbarkeit 65 / 65\n69\nAnlegen: Erhöht die Angriffskraft um 22." }
entries[30314] = { ["name"] = "Teufelsstahlschießeisen", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr , Teufelsstahlstabilisator (4), Eine Hand voll Teufelseisenbolzen (4)\nTeufelsstahlschießeisen\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n104 - 194 Schaden Tempo 2.40\n(62.08 Schaden pro Sekunde)\n+12 Ausdauer\nHaltbarkeit 75 / 75\n70\nAnlegen: Erhöht die kritische Trefferwertung um 13." }
entries[30315] = { ["name"] = "Verschnörkeltes Khoriumgewehr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Khoriumbarren (12), Eine Hand voll Teufelseisenbolzen (4), Edeltopas (2)\nVerschnörkeltes Khoriumgewehr\nWird beim Anlegen gebunden\nDistanz Schusswaffe\n144 - 268 Schaden Tempo 3.10\n(66.45 Schaden pro Sekunde)\n+14 Beweglichkeit\nHaltbarkeit 75 / 75\n70\nAnlegen: Erhöht die Trefferwertung um 13." }
entries[30316] = { ["name"] = "Zahnradbrille", ["text"] = "Wirken in 50 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Knotenhautleder (4), Blutgranat (2), Arkaner Staub (8)\nZahnradbrille\nWird beim Anlegen gebunden\nKopf Leder\n220 Rüstung\n<Zufällige Verzauberung>\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst\n(340)" }
entries[30317] = { ["name"] = "Energieverstärkungsbrille", ["text"] = "Wirken in 50 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Knotenhautleder (4), Flammenspessarit (2), Arkaner Staub (8)\nEnergieverstärkungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n100 Rüstung\n+46 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst\n(340)\nAnlegen: Erhöht die kritische Trefferwertung um 31.\nAnlegen: Erhöht die Zaubermacht um 36." }
entries[30318] = { ["name"] = "Ultraspektropische Enthüllungsbrille", ["text"] = "Wirken in 50 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Knotenhautleder (4), Khoriumbarren (2), Tiefenperidot (2), Kleiner Prismasplitter (2)\nUltraspektropische Enthüllungsbrille\nWird beim Anlegen gebunden\nKopf Stoff\n124 Rüstung\n+36 Ausdauer\nHaltbarkeit 50 / 50\nBenötigt Ingenieurskunst\n(350)\nAnlegen: Erhöht die kritische Trefferwertung um 24.\nAnlegen: Erhöht die Trefferwertung um 24.\nAnlegen: Erhöht Eure Abhärtungswertung um 24.\nAnlegen: Erhöht die Tempowertung um 24.\nBenutzen: Ermöglicht Euch, in weite Entfernungen zu sehen." }
entries[30319] = { ["name"] = "Dämonische Abhärtung", ["text"] = "Verringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe oder Zauber erleidet, um 1%. Verringert jeglichen von Eurem beschworenen Dämon erlittenen Schaden um 5%." }
entries[30320] = { ["name"] = "Dämonische Abhärtung", ["text"] = "Verringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe oder Zauber erleidet, um 2%. Verringert jeglichen von Eurem beschworenen Dämon erlittenen Schaden um 10%." }
entries[30321] = { ["name"] = "Dämonische Abhärtung", ["text"] = "Verringert die Chance, dass Ihr einen kritischen Treffer durch Nahkampfangriffe oder Zauber erleidet, um 3%. Verringert jeglichen von Eurem beschworenen Dämon erlittenen Schaden um 15%." }
entries[30324] = { ["name"] = "Heldenhafter Stoß", ["text"] = "15 Wut Nahkampfreichweite\nNächster Nahkampf\nBenötigt Nahkampfwaffe\nEin heftiger Angriff, der den Nahkampfschaden um 317 erhöht und ein hohes Maß an Bedrohung erzeugt. Verursacht 111 zusätzlichen Schaden gegen benommene Ziele." }
entries[30325] = { ["name"] = "Extremsichtbrille", ["text"] = "Wirken in 50 sek.\nTools:\nBogenlichtschraubenschlüssel , Gyromatischer Mikroregler\nReagenzien:\nSchweres Knotenhautleder (4), Khoriumbarren (2), Nachtauge (2), Großer Prismasplitter (2)\nExtremsichtbrille\nWird beim Anlegen gebunden\nKopf Leder\n232 Rüstung\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst\n(360)\nAnlegen: Erhöht die Trefferwertung um 23.\nAnlegen: Erhöht die Angriffskraft um 84.\nBenutzen: Erhöht 15 sec lang Eure Verstohlenheitsentdeckung. (2 Min Abklingzeit)" }
entries[30326] = { ["name"] = "Mananachschub", ["text"] = "Wenn Ihr durch 'Mana entziehen' oder 'Aderlass' Mana bekommt, erhält Euer beschworener Dämon 100% des von Euch gewonnenen Manas." }
entries[30329] = { ["name"] = "Adamantitzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitbarren (8), Golddraenit (2)\nAdamantitzielfernrohr\n55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 10.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[30330] = { ["name"] = "Tödlicher Stoß", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 6 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nEin heimtückischer Stoß, der Waffenschaden plus 210 verursacht und das Ziel verwundet sowie die Wirksamkeit jeglicher Heilung 10 sec lang um 50% verringert." }
entries[30331] = { ["name"] = "Zanzas ewiger Glanz", ["text"] = "100 Meter Reichweite\nSofort\nErhöht die Chance, feindliche Zauber zu reflektieren, um 3%. Hält 2 hrs lang an. Der erste Angriffszauber gegen den Nutzer wird automatisch reflektiert. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
entries[30332] = { ["name"] = "Khoriumzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr , Khoriumbarren (4), Dämmerstein (2)\nKhoriumzielfernrohr\n55\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht den damit zugefügten Schaden um 12." }
entries[30334] = { ["name"] = "Geeichtes Eterniumzielfernrohr", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Teufelsstahlstabilisator (6), Stern der Elune (2)\nGeeichtes Eterniumzielfernrohr\n60\nBenutzen: Verbindet ein Zielfernrohr dauerhaft mit dem Bogen oder der Schusswaffe und erhöht die kritische Trefferwertung dieser Waffe um 28.\n\nDurch das Anbringen des Fernrohrs an die Fernkampfwaffe wird diese seelengebunden." }
entries[30335] = { ["name"] = "Blutdurst", ["text"] = "30 Wut Nahkampfreichweite\nSpontanzauber 4 sek. Abklingzeit\nGreift das Ziel sofort an und verursacht (Attack power * 45 / 100) Schaden. Zusätzlich werden die nächsten erfolgreichen 0 Nahkampfangriffe 45 Gesundheit wiederherstellen. Dieser Effekt hält until cancelled lang an. Schaden basiert auf Angriffskraft." }
entries[30336] = { ["name"] = "Zanzas ewiger Geist", ["text"] = "100 Meter Reichweite\nSofort\nErhöht 2 hrs lang die Willenskraft des Spielers um 50 und die Ausdauer um 50. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
entries[30337] = { ["name"] = "Krachbummroboter", ["text"] = "Wirken in 50 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nAdamantitrahmen , Teufelseisengehäuse (2), Goldkraftkern , Eine Hand voll Teufelseisenbolzen (2)\nKrachbummroboter\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Rechtsklicken, um einen robotischen Begleiter zu beschwören, der gegen andere Roboter kämpfen wird. (3 Min Abklingzeit)" }
entries[30338] = { ["name"] = "Zanzas ewige Schnelligkeit", ["text"] = "100 Meter Reichweite\nSofort\nErhöht das Lauftempo des Spielers 2 hrs lang um 20%. Es kann immer nur der Effekt von jeweils einem Zanzatrank aktiv sein." }
