entries[30474] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 120% des normalen Waffenschadens. Zusätzlich stellen die nächsten 5 erfolgreichen Nahkampfangriffe 238 to 262 Gesundheit wieder her. Dieser Effekt hält 10 sec lang an." }
