entries[30562] = { ["name"] = "Vermächtnis des Bergkönigs", ["text"] = "Sofort\nBricht das Siegel des Buches und gewährt Euch eine Chance, Eure Rüstung und Euren Magiewiderstand zu erhöhen, wenn Ihr im Gefecht getroffen werdet.\n(Procchance: 3%)" }
entries[30563] = { ["name"] = "Goblinraketenwerfer", ["text"] = "Wirken in 12.5 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärtetes Adamantitrohr (2), Khoriumkraftkern , Teufelsstahlstabilisator (2), Urfeuer (6), Urerde (6), Empfindlicher Arkanitwandler (2)\nGoblinraketenwerfer\nWird beim Anlegen gebunden\nSchmuck\n+45 Ausdauer\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nBenutzen: Feuert eine mächtige Rakete auf den Gegner, die 960 to 1440 Schaden verursacht und ihn 3 Sek. lang betäubt. Das Ding hat aber einen ziemlichen Rückstoß... (2 Min Abklingzeit)" }
entries[30564] = { ["name"] = "Groll des Worgen", ["text"] = "Sofort\nVerwandelt den Zaubernden in einen Worgen. Dadurch fügen Nahkampf- und Distanzangriffe 200 Schattenschaden zu.\n(2s Abklingzeit)" }
entries[30565] = { ["name"] = "Verzauberter Helm des Vorarbeiters", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nSchattenstoff (4), Urmana (12), Urluft (12)\nVerzauberter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Stoff\n132 Rüstung\n+48 Ausdauer\n+30 Intelligenz\nHaltbarkeit 60 / 60\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nAnlegen: +10% Betäubungswiderstand.\nAnlegen: Erhöht die Zaubermacht um 36." }
entries[30566] = { ["name"] = "Verstärkter Helm des Vorarbeiters", ["text"] = "Wirken in 45 sek.\nTools:\nSchmiedehammer , Bogenlichtschraubenschlüssel\nReagenzien:\nGehärteter Adamantitbarren (8), Urerde (12), Urfeuer (12)\nVerstärkter Helm des Vorarbeiters\nWird beim Aufheben gebunden\nKopf Kette\n550 Rüstung\n+30 Beweglichkeit\n+48 Ausdauer\nHaltbarkeit 85 / 85\nBenötigt Ingenieurskunst\n(350)\nBenötigt Gobliningenieur\nAnlegen: Erhöht die Angriffskraft um 62.\nAnlegen: Erhöht Eure Chance, Betäubungs- und Desorientierungseffekten zu widerstehen, um 10%." }
