entries[30980] = { ["name"] = "Kopfnuss", ["text"] = "15 Meter Reichweite\nSofort\nBenötigt Verstohlenheit\nMacht ein Ziel bis zu 8 sec lang handlungsunfähig. Muss im Verstohlenheitsmodus sein. Wirkt nur bei Humanoiden, die sich nicht im Kampf befinden. Jeglicher erlittene Schaden wird das Ziel wiederbeleben. Es kann immer nur ein Ziel von der Fähigkeit 'Kopfnuss' betroffen sein." }
