entries[31016] = { ["name"] = "Ausweiden", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden pro Combopunkt verursacht:\n1 Punkt: [54 + ((170) + Attack power * 0.03) * ( 1 ) ]-[162 + ((170) + Attack power * 0.07) * ( 1 ) ] Schaden\n2 Punkte: [54 + ((340) + Attack power * 0.06) * ( 1 ) ]-[162 + ((340) + Attack power * 0.14) * ( 1 ) ] Schaden\n3 Punkte: [54 + ((510) + Attack power * 0.09) * ( 1 ) ]-[162 + ((510) + Attack power * 0.21) * ( 1 ) ] Schaden\n4 Punkte: [54 + ((680) + Attack power * 0.12) * ( 1 ) ]-[162 + ((680) + Attack power * 0.28) * ( 1 ) ] Schaden\n5 Punkte: [54 + ((850) + Attack power * 0.15) * ( 1 ) ]-[162 + ((850) + Attack power * 0.35) * ( 1 ) ] Schaden" }
entries[31018] = { ["name"] = "Wilder Biss", ["text"] = "35 Energie Nahkampfreichweite\nSofort\nBenötigt Katzengestalt\nFinishing-Move, der Schaden pro Combopunkt verursacht und vorhandene Energiepunkte (bis zu maximal 30) in jeweils (2.0999999 + Attack power / 410) zusätzlichen Schaden umwandelt. Schaden wird durch Angriffskraft erhöht.\n1 Punkt: (52 + 147 * 1 + 0.07 * Attack power)-(112 + 147 * 1 + 0.07 * Attack power) Schaden\n2 Punkte: (52 + 147 * 2 + 0.14 * Attack power)-(112 + 147 * 2 + 0.14 * Attack power) Schaden\n3 Punkte: (52 + 147 * 3 + 0.21 * Attack power)-(112 + 147 * 3 + 0.21 * Attack power) Schaden\n4 Punkte: (52 + 147 * 4 + 0.28 * Attack power)-(112 + 147 * 4 + 0.28 * Attack power) Schaden\n5 Punkte: (52 + 147 * 5 + 0.35 * Attack power)-(112 + 147 * 5 + 0.35 * Attack power) Schaden" }
