entries[31255] = { ["name"] = "Tödliche Schnelligkeit", ["text"] = "Erhöht Euer Bewegungstempo immer um 10%, wenn ihr einem Ziel Schaden zufügt, das weniger als 20% Gesundheit hat.\n(5s Abklingzeit)" }
entries[31256] = { ["name"] = "Frostrüstung", ["text"] = "150 Mana\nSofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Frostschicht, die 10 sec lang bestehen bleibt. Das dicke Eis erhöht die Rüstung um 3000, verlangsamt das Bewegungstempo von Nahkampfangreifern um 50% und erhöht die Zeit zwischen ihren Angriffen um 25%.\n(2s Abklingzeit)" }
entries[31257] = { ["name"] = "Kälte", ["text"] = "30 Meter Reichweite\nSofort\nUnterkühlt Angreifer, verlangsamt ihr Bewegungstempo um 50% und ihr Angriffstempo um 25%." }
entries[31258] = { ["name"] = "Tod & Verfall", ["text"] = "320 Mana 40 Meter Reichweite\nWirken in 1 sek.\nRuft die bösartigen Kräfte von Tod und Verfall herbei, um in einem ausgewählten Gebiet 15 sec lang Schattenschaden zuzufügen." }
entries[31259] = { ["name"] = "Giftwolke", ["text"] = "30 Meter Reichweite\nSofort\nFügt 30 sec lang in der Nähe befindlichen Feinden alle 2 Sek. 500 Naturschaden zu." }
entries[31260] = { ["name"] = "Aura der Brillanz" }
entries[31261] = { ["name"] = "Permanentes Totstellen" }
entries[31262] = { ["name"] = "Feuerball", ["text"] = "50 Meter Reichweite\nWirken in 1.5 sek.\nFügt einem Gegner 1700 to 2300 Feuerschaden zu." }
entries[31263] = { ["name"] = "Pyroschlag", ["text"] = "40 Meter Reichweite\nWirken in 5 sek.\nFügt einem Gegner 4625 to 5375 Feuerschaden zu und versengt ihn 9 sec lang für zusätzliche 500 Schaden alle 3 Sek." }
entries[31264] = { ["name"] = "Wasserelementare beschwören", ["text"] = "200 Mana\nWirken in 0.5 sek.\nBeschwört 3 mächtige Wasserelementare, die den Zaubernden unterstützen." }
entries[31266] = { ["name"] = "Blizzard", ["text"] = "150 Mana 30 Meter Reichweite\nWirken in 1 sek.\nRuft einen Blizzard herbei, der 10 sec lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. 950 to 1050 Frostschaden zufügt." }
entries[31267] = { ["name"] = "Teleporter" }
entries[31268] = { ["name"] = "Drachenknochen einäschern", ["text"] = "5 Meter Reichweite\nWirken in 5 sek.\nPlatziert die Knochen auf dem ewig brennenden Scheiterhaufen." }
entries[31269] = { ["name"] = "Rauchwolke freigeben" }
entries[31270] = { ["name"] = "Mondfeuer", ["text"] = "95 Mana 30 Meter Reichweite\nSofort\nVerbrennt den Gegner mit Arkanschaden." }
entries[31271] = { ["name"] = "Dornen", ["text"] = "30 Meter Reichweite\nSofort\nAus dem befreundeten Ziel sprießen Dornen, die jedem Angreifer 1 Naturschaden zufügen. Hält 10 min lang an." }
entries[31272] = { ["name"] = "Windschock", ["text"] = "19 Mana 30 Meter Reichweite\nSofort\nÜberzieht einen Gegner mit der Macht des Windes und verursacht Naturschaden. Verursacht 10 sec lang bleibenden Naturschaden." }
entries[31273] = { ["name"] = "Schrei", ["text"] = "Nahkampfreichweite\nSofort\nVerringert die Angriffskraft naher Gegner." }
entries[31274] = { ["name"] = "Niederschlagen", ["text"] = "Nahkampfreichweite\nSofort\nFügt einem Feind 35 Schaden zu und betäubt ihn 1 sec lang." }
entries[31275] = { ["name"] = "Wässriger Schlag", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nSchlägt einen Feind und fügt Waffenschaden plus 5 zu." }
entries[31277] = { ["name"] = "Stampfen", ["text"] = "10 Meter Reichweite\nSofort\nErschüttert den Boden und fügt nahen Gegnern normalen Schaden zu." }
entries[31279] = { ["name"] = "Prankenhieb", ["text"] = "Nahkampfreichweite\nSofort\nEin grimmiger Hieb, der dem Ziel und bis zu drei weiteren Gegnern in der Nähe Schaden zufügt." }
entries[31280] = { ["name"] = "Kälte von Blutmythos", ["text"] = "Nahkampfreichweite\nSofort\nErhöht den durch einen Gegner zugefügten Frost- und Feuerschaden 2 min lang um 20." }
entries[31281] = { ["name"] = "Blutfeuer", ["text"] = "90 Mana 40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu und verringert 4 sec lang sein Bewegungstempo." }
entries[31282] = { ["name"] = "Infizierte Wunde", ["text"] = "Nahkampfreichweite\nNächster Nahkampf\nErhöht den erlittenen körperlichen Schaden eines Feindes 30 sec lang um 17." }
entries[31283] = { ["name"] = "Strahlung", ["text"] = "Sofort\nVerursacht bei nahen Feinden Naturschaden." }
entries[31284] = { ["name"] = "Strahlung" }
entries[31285] = { ["name"] = "Vampiraura", ["text"] = "Sofort\nNahkampfangriffe heilen Euch um 300% des verursachten Schadens." }
entries[31286] = { ["name"] = "Peitsche", ["text"] = "Nahkampfreichweite\nSofort 20 sek. Abklingzeit\nFügt einem Gegner 4 sec lang Schaden zu und hat eine Chance, ihn zu entwaffnen." }
entries[31287] = { ["name"] = "Wucherwurzeln", ["text"] = "30 Meter Reichweite\nWirken in 1.5 sek.\nUmwickelt einen Feind mit Wurzeln, macht ihn bis zu 2 sec lang bewegungsunfähig und fügt ihm alle 1 Sek. Naturschaden zu." }
